const std = @import("std");
const builtin = @import("builtin");

const lib = struct {
    pub fn zig_initialize_kernel() c_int {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer {
            _ = gpa.deinit();
        }
        const allocator = gpa.allocator();
        const test_bytes: usize = 1024;
        const buf = allocator.alignedAlloc(u8, @alignOf(u8), test_bytes) catch return -1;
        defer allocator.free(buf);
        if (buf.len != test_bytes) return -1;
        for (buf) |*b| b.* = 0xA5;
        var acc: usize = 0;
        for (buf) |b| acc +%= b;
        if (acc == 0) return -1;
        return 0;
    }

    pub fn zig_hardware_intrinsics_available() c_int {
        var query = std.Target.Query.fromTarget(builtin.target);
        query.cpu_model = .native;
        const native_target = std.zig.system.resolveTargetQuery(query) catch return 0;
        switch (builtin.target.cpu.arch) {
            .x86_64, .x86 => {
                const x86 = std.Target.x86;
                const has_avx = native_target.cpu.features.isEnabled(.avx);
                const has_avx2 = native_target.cpu.features.isEnabled(.avx2);
                return if (has_avx and has_avx2) 1 else 0;
            },
            else => return 0,
        }
    }

    pub fn zig_compute_protein_energy(coords: [*]const f64, atom_count: usize, energy_out: *f64) c_int {
        if (coords == null or energy_out == null or atom_count == 0) return -1;
        var total: f64 = 0.0;
        var i: usize = 0;
        while (i < atom_count) : (i += 1) {
            const ix = coords[i * 3 + 0];
            const iy = coords[i * 3 + 1];
            const iz = coords[i * 3 + 2];
            var j: usize = i + 1;
            while (j < atom_count) : (j += 1) {
                const jx = coords[j * 3 + 0];
                const jy = coords[j * 3 + 1];
                const jz = coords[j * 3 + 2];
                const dx = ix - jx;
                const dy = iy - jy;
                const dz = iz - jz;
                const r2 = dx * dx + dy * dy + dz * dz;
                if (r2 > 0.0) {
                    const inv_r2 = 1.0 / r2;
                    const inv_r6 = inv_r2 * inv_r2 * inv_r2;
                    const inv_r12 = inv_r6 * inv_r6;
                    const lj = 4.0 * (inv_r12 - inv_r6);
                    total += lj;
                }
            }
        }
        energy_out.* = total;
        return 0;
    }

    pub fn zig_simd_sequence_analysis(seq_ptr: [*]const u8, seq_len: usize, gc_out: *f64) c_int {
        if (seq_ptr == null or gc_out == null or seq_len == 0) return -1;
        const has_simd: bool = zig_hardware_intrinsics_available() == 1;
        var gc_count: usize = 0;
        if (has_simd and (builtin.target.cpu.arch == .x86_64 or builtin.target.cpu.arch == .x86)) {
            const VL: usize = 32;
            var i: usize = 0;
            const ones_u8: @Vector(VL, u8) = @splat(1);
            const zeros_u8: @Vector(VL, u8) = @splat(0);
            const mask_up: @Vector(VL, u8) = @splat(0xDF);
            const Gv: @Vector(VL, u8) = @splat(@as(u8, 'G'));
            const Cv: @Vector(VL, u8) = @splat(@as(u8, 'C'));
            while (i + VL <= seq_len) : (i += VL) {
                const chunk: [VL]u8 = @ptrCast(*const [VL]u8, seq_ptr + i).*;
                const v: @Vector(VL, u8) = @bitCast(chunk);
                const upper: @Vector(VL, u8) = v & mask_up;
                const eqG_mask: @Vector(VL, bool) = upper == Gv;
                const eqC_mask: @Vector(VL, bool) = upper == Cv;
                const eqG_u8: @Vector(VL, u8) = @select(u8, eqG_mask, ones_u8, zeros_u8);
                const eqC_u8: @Vector(VL, u8) = @select(u8, eqC_mask, ones_u8, zeros_u8);
                const sum_u8: @Vector(VL, u8) = eqG_u8 + eqC_u8;
                const lane_sum: u16 = @intCast(u16, @reduce(.Add, @as(@Vector(VL, u16), sum_u8)));
                gc_count += lane_sum;
            }
            while (i < seq_len) : (i += 1) {
                var b: u8 = (seq_ptr + i).*;
                b &= 0xDF;
                if (b == 'G' or b == 'C') gc_count += 1;
            }
        } else {
            var i: usize = 0;
            while (i < seq_len) : (i += 1) {
                var b: u8 = (seq_ptr + i).*;
                b &= 0xDF;
                if (b == 'G' or b == 'C') gc_count += 1;
            }
        }
        gc_out.* = (@as(f64, @floatFromInt(gc_count)) / @as(f64, @floatFromInt(seq_len))) * 100.0;
        return 0;
    }

    pub fn zig_allocate_protein_buffer(atom_count: usize) ?*anyopaque {
        if (atom_count == 0) return null;
        const bytes = atom_count * 3 * @sizeOf(f64);
        const p = std.c.malloc(bytes);
        if (p == null) return null;
        return p;
    }

    pub fn zig_free_protein_buffer(p: ?*anyopaque) void {
        if (p) |ptr| {
            std.c.free(ptr);
        }
    }
};

