pub const MemoryPool = struct {
    allocator: std.mem.Allocator,
    blocks: std.ArrayList([]u8),
    available_blocks: std.ArrayList(usize),
    block_size: usize,
    total_allocated: usize,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: std.mem.Allocator, block_size: usize, initial_blocks: usize) !MemoryPool {
        var pool = MemoryPool{
            .allocator = allocator,
            .blocks = std.ArrayList([]u8).init(allocator),
            .available_blocks = std.ArrayList(usize).init(allocator),
            .block_size = block_size,
            .total_allocated = 0,
            .mutex = std.Thread.Mutex{},
        };

        var i: usize = 0;
        while (i < initial_blocks) : (i += 1) {
            const block = try allocator.alloc(u8, block_size);
            try pool.blocks.append(block);
            try pool.available_blocks.append(i);
            pool.total_allocated += block_size;
        }

        return pool;
    }

    pub fn acquire(self: *MemoryPool) ![]u8 {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.available_blocks.items.len == 0) {
            const block = try self.allocator.alloc(u8, self.block_size);
            try self.blocks.append(block);
            self.total_allocated += self.block_size;
            return block;
        }

        const idx = self.available_blocks.pop();
        return self.blocks.items[idx];
    }

    pub fn release(self: *MemoryPool, block: []u8) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        for (self.blocks.items, 0..) |b, i| {
            if (b.ptr == block.ptr) {
                try self.available_blocks.append(i);
                return;
            }
        }
    }

    pub fn deinit(self: *MemoryPool) void {
        for (self.blocks.items) |block| {
            self.allocator.free(block);
        }
        self.blocks.deinit();
        self.available_blocks.deinit();
    }
};

pub const RingBuffer = struct {
    buffer: []u8,
    read_pos: usize,
    write_pos: usize,
    capacity: usize,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !RingBuffer {
        return RingBuffer{
            .buffer = try allocator.alloc(u8, capacity),
            .read_pos = 0,
            .write_pos = 0,
            .capacity = capacity,
            .mutex = std.Thread.Mutex{},
        };
    }

    pub fn write(self: *RingBuffer, data: []const u8) !usize {
        self.mutex.lock();
        defer self.mutex.unlock();

        const available = self.capacity - ((self.write_pos - self.read_pos) % self.capacity);
        const to_write = @min(data.len, available);

        if (to_write == 0) return 0;

        var written: usize = 0;
        while (written < to_write) {
            const chunk_size = @min(to_write - written, self.capacity - (self.write_pos % self.capacity));
            const dest_start = self.write_pos % self.capacity;
            @memcpy(self.buffer[dest_start..][0..chunk_size], data[written..][0..chunk_size]);
            written += chunk_size;
            self.write_pos += chunk_size;
        }

        return written;
    }

    pub fn read(self: *RingBuffer, dest: []u8) !usize {
        self.mutex.lock();
        defer self.mutex.unlock();

        const available = (self.write_pos - self.read_pos) % self.capacity;
        const to_read = @min(dest.len, available);

        if (to_read == 0) return 0;

        var read_count: usize = 0;
        while (read_count < to_read) {
            const chunk_size = @min(to_read - read_count, self.capacity - (self.read_pos % self.capacity));
            const src_start = self.read_pos % self.capacity;
            @memcpy(dest[read_count..][0..chunk_size], self.buffer[src_start..][0..chunk_size]);
            read_count += chunk_size;
            self.read_pos += chunk_size;
        }

        return read_count;
    }

    pub fn deinit(self: *RingBuffer, allocator: std.mem.Allocator) void {
        allocator.free(self.buffer);
    }
};

pub const AtomicCounter = struct {
    value: std.atomic.Value(u64),

    pub fn init(initial: u64) AtomicCounter {
        return AtomicCounter{
            .value = std.atomic.Value(u64).init(initial),
        };
    }

    pub fn increment(self: *AtomicCounter) u64 {
        return self.value.fetchAdd(1, .monotonic);
    }

    pub fn decrement(self: *AtomicCounter) u64 {
        return self.value.fetchSub(1, .monotonic);
    }

    pub fn get(self: *AtomicCounter) u64 {
        return self.value.load(.monotonic);
    }

    pub fn set(self: *AtomicCounter, new_value: u64) void {
        self.value.store(new_value, .monotonic);
    }
};

pub const LockFreeQueue = struct {
    const Node = struct {
        data: []u8,
        next: ?*Node,
    };

    head: std.atomic.Value(?*Node),
    tail: std.atomic.Value(?*Node),
    allocator: std.mem.Allocator,
    size: AtomicCounter,

    pub fn init(allocator: std.mem.Allocator) LockFreeQueue {
        return LockFreeQueue{
            .head = std.atomic.Value(?*Node).init(null),
            .tail = std.atomic.Value(?*Node).init(null),
            .allocator = allocator,
            .size = AtomicCounter.init(0),
        };
    }

    pub fn enqueue(self: *LockFreeQueue, data: []const u8) !void {
        const node = try self.allocator.create(Node);
        node.* = Node{
            .data = try self.allocator.dupe(u8, data),
            .next = null,
        };

        var old_tail = self.tail.load(.acquire);
        while (true) {
            if (self.tail.cmpxchgWeak(old_tail, node, .release, .acquire)) |new_old| {
                old_tail = new_old;
                continue;
            }

            if (old_tail) |tail| {
                tail.next = node;
            } else {
                _ = self.head.cmpxchgWeak(null, node, .release, .acquire);
            }
            break;
        }

        _ = self.size.increment();
    }

    pub fn dequeue(self: *LockFreeQueue) ?[]u8 {
        var old_head = self.head.load(.acquire);
        while (old_head) |head| {
            const next = head.next;
            if (self.head.cmpxchgWeak(old_head, next, .release, .acquire)) |new_old| {
                old_head = new_old;
                continue;
            }

            const data = head.data;
            self.allocator.destroy(head);
            _ = self.size.decrement();
            return data;
        }
        return null;
    }

    pub fn len(self: *LockFreeQueue) u64 {
        return self.size.get();
    }

    pub fn deinit(self: *LockFreeQueue) void {
        while (self.dequeue()) |data| {
            self.allocator.free(data);
        }
    }
};

pub const CacheAlignedBuffer = struct {
